 row.get_by_role('button',name='更多操作：'+title,exact=True).click();page.get_by_role('dialog',name='线索操作',exact=True).get_by_role('button',name='紧急程度',exact=True).click();page.get_by_role('dialog',name='设置紧急程度',exact=True).get_by_role('combobox').select_option('2');page.get_by_role('button',name='确认保存',exact=True).click();expect(page.get_by_role('dialog',name='设置紧急程度',exact=True)).to_have_count(0);page.get_by_role('dialog',name='线索操作',exact=True).locator(':scope > header button').click();expect(row.locator('.cross-urgency.urgent')).to_be_visible();checks+=1;assert page.get_by_role('button',name='彻底删除',exact=True).count()==0;checks+=1;page.screenshot(path='/tmp/v327-assignment-urgency.png',full_page=True);c.close()
 page,c=page_for(state['adminCookie']);page.get_by_role('textbox',name='搜索名称',exact=True).fill(title);row=page.locator('tr').filter(has_text=title);row.get_by_role('button',name='更多操作：'+title,exact=True).click();page.get_by_role('dialog',name='线索操作',exact=True).get_by_role('button',name='彻底删除',exact=True).click();expect(page.get_by_text('将永久删除',exact=False)).to_be_visible();page.get_by_label('输入资料名称确认彻底删除',exact=True).fill('错误');page.get_by_role('button',name='确认彻底删除',exact=True).click();expect(page.get_by_text('请输入完整资料名称',exact=True)).to_be_visible();checks+=1;page.get_by_label('输入资料名称确认彻底删除',exact=True).fill(title);page.get_by_role('button',name='确认彻底删除',exact=True).click();expect(row).to_have_count(0);checks+=1;c.close();browser.close();print(json.dumps({'checks':checks,'ordinaryPurgeHidden':True,'publicUpload':True,'assign':True,'urgency':True,'typedDeleteConfirmation':True},ensure_ascii=False))
